import { createServer } from 'node:http';
import { readFileSync } from 'node:fs';
import { openProjects } from './projects.js';
import { projectsPage, projectPage, notFoundPage } from './views.js';
import { TASK_PRIORITIES } from './task-priorities.js';

const projects = openProjects(process.env.DB_PATH || 'data/workboard.sqlite');
const stylesheet = readFileSync(new URL('./public/styles.css', import.meta.url));
const formScript = readFileSync(new URL('./public/forms.js', import.meta.url));

function taskFilter(value) {
  return ['All', 'Open', 'Completed'].includes(value) ? value : 'All';
}

function projectFilter(value) {
  return value === 'Archived' ? 'Archived' : 'Active';
}

function redirect(response, location) {
  response.writeHead(303, { Location: location });
  response.end();
}

function send(response, status, type, body) {
  response.writeHead(status, { 'Content-Type': type, 'X-Content-Type-Options': 'nosniff' });
  response.end(body);
}

async function readForm(request) {
  const chunks = [];
  let size = 0;
  for await (const chunk of request) {
    size += chunk.length;
    if (size > 64 * 1024) {
      const error = new Error('Request too large');
      error.status = 413;
      throw error;
    }
    chunks.push(chunk);
  }
  return new URLSearchParams(Buffer.concat(chunks).toString('utf8'));
}

const server = createServer(async (request, response) => {
  try {
    const url = new URL(request.url, 'http://localhost');
    const path = url.pathname;
    if (request.method === 'GET' && path === '/health') {
      return send(response, 200, 'application/json', JSON.stringify({ status: 'ok' }));
    }
    if (request.method === 'GET' && path === '/styles.css') {
      return send(response, 200, 'text/css; charset=utf-8', stylesheet);
    }
    if (request.method === 'GET' && path === '/forms.js') {
      return send(response, 200, 'text/javascript; charset=utf-8', formScript);
    }
    if (request.method === 'GET' && path === '/') {
      const filter = projectFilter(url.searchParams.get('filter'));
      return send(response, 200, 'text/html; charset=utf-8', projectsPage(projects.list(filter), '', filter));
    }
    if (request.method === 'POST' && path === '/projects') {
      const form = await readForm(request);
      const filter = projectFilter(form.get('filter'));
      if (!projects.create(form.get('name') || '')) {
        return send(response, 400, 'text/html; charset=utf-8',
          projectsPage(projects.list(filter), 'Project name is required', filter));
      }
      return redirect(response, '/');
    }
    const archiveMatch = path.match(/^\/projects\/([1-9]\d*)\/(archive|restore)$/);
    if (request.method === 'POST' && archiveMatch && Number.isSafeInteger(Number(archiveMatch[1]))) {
      if (projects.setArchived(Number(archiveMatch[1]), archiveMatch[2] === 'archive')) {
        return redirect(response, archiveMatch[2] === 'restore' ? '/?filter=Archived' : '/');
      }
    }
    const match = path.match(/^\/projects\/([1-9]\d*)$/);
    if (request.method === 'GET' && match && Number.isSafeInteger(Number(match[1]))) {
      const project = projects.find(Number(match[1]));
      if (project) {
        const filter = taskFilter(url.searchParams.get('filter'));
        return send(response, 200, 'text/html; charset=utf-8',
          projectPage(project, projects.listTasks(project.id, filter), filter));
      }
    }
    const renameMatch = path.match(/^\/projects\/([1-9]\d*)\/rename$/);
    if (request.method === 'POST' && renameMatch && Number.isSafeInteger(Number(renameMatch[1]))) {
      const project = projects.find(Number(renameMatch[1]));
      if (project) {
        if (project.archived) {
          return send(response, 409, 'text/plain; charset=utf-8', 'Archived project');
        }
        const form = await readForm(request);
        const filter = taskFilter(form.get('filter'));
        if (!projects.rename(project.id, form.get('name') || '')) {
          return send(response, 400, 'text/html; charset=utf-8',
            projectPage(project, projects.listTasks(project.id, filter), filter, 'Project name is required'));
        }
        return redirect(response, `/projects/${project.id}?filter=${filter}`);
      }
    }
    const taskMatch = path.match(/^\/projects\/([1-9]\d*)\/tasks(?:\/([1-9]\d*)\/(completion|rename|priority))?$/);
    if (request.method === 'POST' && taskMatch &&
        Number.isSafeInteger(Number(taskMatch[1])) &&
        (!taskMatch[2] || Number.isSafeInteger(Number(taskMatch[2])))) {
      const project = projects.find(Number(taskMatch[1]));
      if (project) {
        if (project.archived) {
          return send(response, 409, 'text/plain; charset=utf-8', 'Archived project');
        }
        const form = await readForm(request);
        const filter = taskFilter(form.get('filter'));
        if (taskMatch[3] === 'rename') {
          const title = (form.get('title') || '').trim();
          if (!title) {
            return send(response, 400, 'text/html; charset=utf-8',
              projectPage(project, projects.listTasks(project.id, filter), filter, 'Task title is required'));
          }
          if (!projects.renameTask(project.id, Number(taskMatch[2]), title)) {
            return send(response, 404, 'text/html; charset=utf-8', notFoundPage());
          }
        } else if (taskMatch[3] === 'priority') {
          const priority = form.get('priority');
          if (!TASK_PRIORITIES.includes(priority)) {
            return send(response, 400, 'text/html; charset=utf-8',
              projectPage(project, projects.listTasks(project.id, filter), filter, 'Invalid task priority'));
          }
          if (!projects.setTaskPriority(project.id, Number(taskMatch[2]), priority)) {
            return send(response, 404, 'text/html; charset=utf-8', notFoundPage());
          }
        } else if (taskMatch[2]) {
          if (!projects.setTaskCompleted(project.id, Number(taskMatch[2]), form.has('completed'))) {
            return send(response, 404, 'text/html; charset=utf-8', notFoundPage());
          }
        } else if (!projects.createTask(project.id, form.get('title') || '')) {
          return send(response, 400, 'text/html; charset=utf-8',
            projectPage(project, projects.listTasks(project.id, filter), filter, 'Task title is required'));
        }
        return redirect(response, `/projects/${project.id}?filter=${filter}`);
      }
    }
    send(response, 404, 'text/html; charset=utf-8', notFoundPage());
  } catch (error) {
    if (!error.status) console.error(error);
    send(response, error.status || 500, 'text/plain; charset=utf-8',
      error.status ? error.message : 'Internal server error');
  }
});

server.listen(Number(process.env.PORT || 8080), '0.0.0.0', () => {
  console.log(`Workboard listening on port ${server.address().port}`);
});

for (const signal of ['SIGINT', 'SIGTERM']) {
  process.on(signal, () => {
    server.close(() => {
      projects.close();
      process.exit(0);
    });
  });
}
import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';
import { TASK_PRIORITIES } from './task-priorities.js';

export function openProjects(databasePath) {
  mkdirSync(dirname(databasePath), { recursive: true });
  const database = new DatabaseSync(databasePath);
  database.exec('PRAGMA foreign_keys = ON');
  database.exec(`
    CREATE TABLE IF NOT EXISTS projects (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT NOT NULL CHECK(length(trim(name)) > 0)
    );
    CREATE TABLE IF NOT EXISTS tasks (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      project_id INTEGER NOT NULL REFERENCES projects(id),
      title TEXT NOT NULL CHECK(length(trim(title)) > 0),
      completed INTEGER NOT NULL DEFAULT 0 CHECK(completed IN (0, 1))
    );
    CREATE INDEX IF NOT EXISTS tasks_project_id ON tasks(project_id);
  `);
  if (!database.prepare('PRAGMA table_info(projects)').all().some((column) => column.name === 'archived')) {
    database.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN (0, 1))');
  }
  if (!database.prepare('PRAGMA table_info(tasks)').all().some((column) => column.name === 'priority')) {
    database.exec("ALTER TABLE tasks ADD COLUMN priority TEXT NOT NULL DEFAULT 'Normal' CHECK(priority IN ('Low', 'Normal', 'High'))");
  }
  const list = database.prepare(`
    SELECT projects.id, projects.name, projects.archived,
      COUNT(tasks.id) AS total_count, COALESCE(SUM(tasks.completed), 0) AS completed_count
    FROM projects LEFT JOIN tasks ON tasks.project_id = projects.id
    WHERE projects.archived = ? GROUP BY projects.id ORDER BY projects.id
  `);
  const find = database.prepare('SELECT id, name, archived FROM projects WHERE id = ?');
  const insert = database.prepare('INSERT INTO projects (name) VALUES (?)');
  const updateArchive = database.prepare('UPDATE projects SET archived = ? WHERE id = ?');
  const updateName = database.prepare('UPDATE projects SET name = ? WHERE id = ? AND archived = 0');
  const listTasks = database.prepare(`
    SELECT id, title, completed, priority FROM tasks
    WHERE project_id = ? AND (? IS NULL OR completed = ?) ORDER BY id
  `);
  const insertTask = database.prepare(`
    INSERT INTO tasks (project_id, title)
    SELECT id, ? FROM projects WHERE id = ? AND archived = 0
  `);
  const updateTask = database.prepare(`
    UPDATE tasks SET completed = ? WHERE id = ? AND project_id = ?
      AND EXISTS (SELECT 1 FROM projects WHERE id = tasks.project_id AND archived = 0)
  `);
  const updateTaskTitle = database.prepare(`
    UPDATE tasks SET title = ? WHERE id = ? AND project_id = ?
      AND EXISTS (SELECT 1 FROM projects WHERE id = tasks.project_id AND archived = 0)
  `);
  const updateTaskPriority = database.prepare(`
    UPDATE tasks SET priority = ? WHERE id = ? AND project_id = ?
      AND EXISTS (SELECT 1 FROM projects WHERE id = tasks.project_id AND archived = 0)
  `);

  return {
    list: (filter = 'Active') => list.all(filter === 'Archived' ? 1 : 0),
    find: (id) => find.get(id),
    setArchived(id, archived) {
      return updateArchive.run(archived ? 1 : 0, id).changes > 0;
    },
    create(name) {
      const trimmedName = name.trim();
      if (!trimmedName) return false;
      insert.run(trimmedName);
      return true;
    },
    rename(id, name) {
      const trimmedName = name.trim();
      if (!trimmedName) return false;
      return updateName.run(trimmedName, id).changes > 0;
    },
    listTasks(projectId, filter = 'All') {
      const completed = filter === 'Open' ? 0 : filter === 'Completed' ? 1 : null;
      return listTasks.all(projectId, completed, completed);
    },
    createTask(projectId, title) {
      const trimmedTitle = title.trim();
      if (!trimmedTitle) return false;
      return insertTask.run(trimmedTitle, projectId).changes > 0;
    },
    setTaskCompleted(projectId, taskId, completed) {
      return updateTask.run(completed ? 1 : 0, taskId, projectId).changes > 0;
    },
    renameTask(projectId, taskId, title) {
      const trimmedTitle = title.trim();
      if (!trimmedTitle) return false;
      return updateTaskTitle.run(trimmedTitle, taskId, projectId).changes > 0;
    },
    setTaskPriority(projectId, taskId, priority) {
      if (!TASK_PRIORITIES.includes(priority)) return false;
      return updateTaskPriority.run(priority, taskId, projectId).changes > 0;
    },
    close: () => database.close(),
  };
}
export const TASK_PRIORITIES = Object.freeze(['Low', 'Normal', 'High']);
import { TASK_PRIORITIES } from './task-priorities.js';

function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g, (character) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
  })[character]);
}

function page(title, content) {
  return `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${escapeHtml(title)} · Workboard</title>
  <link rel="stylesheet" href="/styles.css">
  <script src="/forms.js" defer></script>
</head>
<body><main>${content}</main></body>
</html>`;
}

export function projectsPage(projects, error = '', filter = 'Active') {
  return page('Projects', `
    <h1>Workboard</h1>
    <form action="/projects" method="post" class="create-project">
      <input type="hidden" name="filter" value="${escapeHtml(filter)}">
      <label for="project-name">Project name</label>
      <div class="form-controls">
        <input id="project-name" name="name" type="text" autocomplete="off">
        <button type="submit">Create project</button>
      </div>
    </form>
    ${error ? `<p role="alert">${escapeHtml(error)}</p>` : ''}
    <form action="/" method="get" class="project-filter" data-auto-submit>
      <label for="project-filter">Project filter</label>
      <select id="project-filter" name="filter">
        ${['Active', 'Archived'].map((option) =>
          `<option${option === filter ? ' selected' : ''}>${option}</option>`).join('')}
      </select>
    </form>
    <section aria-label="Projects" class="project-list">
      ${projects.length ? projects.map((project) => `
        <div data-testid="project-row" class="project-row">
          <span>${escapeHtml(project.name)}</span>
          <span data-testid="project-summary">${project.completed_count}/${project.total_count} completed</span>
          <form action="/projects/${project.id}" method="get">
            <button type="submit">Open project</button>
          </form>
          <form action="/projects/${project.id}/${project.archived ? 'restore' : 'archive'}" method="post">
            <button type="submit">${project.archived ? 'Restore project' : 'Archive project'}</button>
          </form>
        </div>`).join('') : '<p class="empty">Your projects will appear here.</p>'}
    </section>`);
}

export function projectPage(project, tasks = [], filter = 'All', error = '') {
  const projectPath = `/projects/${project.id}`;
  return page(project.name, `
    <form action="/" method="get"><button type="submit">Projects</button></form>
    <h1>${escapeHtml(project.name)}</h1>
    ${project.archived ? '<p>Archived project</p>' : ''}
    <form action="${projectPath}/rename" method="post">
      <input type="hidden" name="filter" value="${escapeHtml(filter)}">
      <label for="new-project-name">New project name</label>
      <div class="form-controls">
        <input id="new-project-name" name="name" type="text" autocomplete="off"${project.archived ? ' disabled' : ''}>
        <button type="submit"${project.archived ? ' disabled' : ''}>Rename project</button>
      </div>
    </form>
    <form action="${projectPath}/tasks" method="post">
      <input type="hidden" name="filter" value="${escapeHtml(filter)}">
      <label for="task-title">Task title</label>
      <div class="form-controls">
        <input id="task-title" name="title" type="text" autocomplete="off">
        <button type="submit"${project.archived ? ' disabled' : ''}>Create task</button>
      </div>
    </form>
    ${error ? `<p role="alert">${escapeHtml(error)}</p>` : ''}
    <form action="${projectPath}" method="get" class="task-filter" data-auto-submit>
      <label for="task-filter">Task filter</label>
      <select id="task-filter" name="filter">
        ${['All', 'Open', 'Completed'].map((option) =>
          `<option${option === filter ? ' selected' : ''}>${option}</option>`).join('')}
      </select>
    </form>
    <section aria-label="Tasks" class="task-list">
      ${tasks.length ? tasks.map((task) => `
        <div data-testid="task-row" class="task-row">
          <span>${escapeHtml(task.title)}</span>
          <form action="${projectPath}/tasks/${task.id}/completion" method="post" data-auto-submit>
            <input type="hidden" name="filter" value="${escapeHtml(filter)}">
            <input type="checkbox" name="completed" aria-label="Complete ${escapeHtml(task.title)}"${task.completed ? ' checked' : ''}${project.archived ? ' disabled' : ''}>
          </form>
          <form action="${projectPath}/tasks/${task.id}/priority" method="post" data-auto-submit>
            <input type="hidden" name="filter" value="${escapeHtml(filter)}">
            <label for="task-priority-${task.id}">Task priority</label>
            <select id="task-priority-${task.id}" name="priority"${project.archived ? ' disabled' : ''}>
              ${TASK_PRIORITIES.map((priority) =>
                `<option${priority === task.priority ? ' selected' : ''}>${priority}</option>`).join('')}
            </select>
          </form>
          <form action="${projectPath}/tasks/${task.id}/rename" method="post" class="task-rename">
            <input type="hidden" name="filter" value="${escapeHtml(filter)}">
            <label for="new-task-title-${task.id}">New task title</label>
            <input id="new-task-title-${task.id}" name="title" type="text" autocomplete="off"${project.archived ? ' disabled' : ''}>
            <button type="submit"${project.archived ? ' disabled' : ''}>Rename task</button>
          </form>
        </div>`).join('') : '<p class="empty">No tasks match this filter.</p>'}
    </section>`);
}

export function notFoundPage() {
  return page('Page not found', '<h1>Page not found</h1><a href="/">Projects</a>');
}
