:root {
  font-family: system-ui, sans-serif;
  color: #192d40;
  background: #f4f6f8;
  line-height: 1.5;
}
* { box-sizing: border-box; }
body { margin: 0; }
main { max-width: 760px; margin: 64px auto; padding: 0 24px; }
h1 { font-size: 2rem; overflow-wrap: anywhere; }
label { display: block; font-weight: 600; margin-bottom: 8px; }
.form-controls { display: flex; gap: 12px; }
input { flex: 1; min-width: 0; border: 1px solid #7b8d9e; border-radius: 6px; padding: 10px 12px; font: inherit; }
button { border: 1px solid #214f78; border-radius: 6px; padding: 10px 16px; background: #214f78; color: white; font: inherit; cursor: pointer; }
button:hover { background: #163a5b; }
button:focus-visible, input:focus-visible, select:focus-visible, a:focus-visible { outline: 3px solid #b05b00; outline-offset: 3px; }
.project-list, .task-list, .task-filter, .project-filter { margin-top: 32px; }
.project-row { flex-wrap: wrap; }
